    25	
    26	    private static String basePath = Paths.get(".").toAbsolutePath().normalize().toString();
    27	    public static final String temp = basePath + "/temp/";
    28	
    29	    /**
    30	     * This method is used to convert the exception to the json string to write into the file
    31	     * 
    32	     * @param exception
    33	     */
    34	    public static void createStackTraceFile( Exception exception )
    35	    {
    36	        try
    37	        {
    38	            ObjectMapper objectMapper = new ObjectMapper();
    39	            HashMap errorHashMap = objectMapper.readValue(objectMapper.writeValueAsString(exception), HashMap.class);
    40	            List<HashMap<String, String>> stackTrace = (List) errorHashMap.get("stackTrace");
    41	            List<HashMap<String, String>> newStackTrace = new ArrayList<>();
    42	
    43	            for( HashMap<String, String> entry : stackTrace )
    44	            {
    45	                if( entry.get("className").contains("finbit") )
    46	                    newStackTrace.add(entry);
    47	            }
    48	
    49	            errorHashMap.put("stackTrace", newStackTrace);
    50	            errorHashMap.remove("cause");
    51	            errorHashMap.remove("suppressed");
    52	
    53	            writeJsonFile(errorHashMap, MDC.get("logId"));
    54	        }
    55	        catch( Exception e )
    56	        {
    57	            log.error("Error while writing Exception to file", e);
    58	        }
    59	    }
    60	
    61	    /**
    62	     * This method is used to write the json file with the pretty printer
    63	     * 
    64	     * @param content
    65	     * @param fileName
    66	     */
    67	    public static File writeJsonFile( Object content, String fileName )
    68	    {
    69	        try
    70	        {
    71	            ObjectMapper objectMapper = new ObjectMapper();
    72	            objectMapper.configure(MapperFeature.SORT_PROPERTIES_ALPHABETICALLY, true);
    73	            objectMapper.configure(SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS, true);
    74	
    75	            File theDir = new File(temp);
    76	            if( !theDir.exists() )
    77	                theDir.mkdir();
    78	
    79	            String absolutePath = temp + fileName + ".json";
    80	            FileWriter fw = new FileWriter(absolutePath, true);
    81	            fw.write(objectMapper.writerWithDefaultPrettyPrinter().writeValueAsString(content));
    82	            fw.close();
    83	
    84	            return new File(absolutePath);
    85	        }
    86	        catch( Exception e )
    87	        {
    88	            log.error("Error while writing json file", e);
    89	        }
    90	        return null;
