    51	     */
    52	
    53	    public <T> T getClaimFromToken( String token, Function<Claims, T> claimsResolver )
    54	    {
    55	        final Claims claims = getAllClaimsFromToken(token);
    56	        return claimsResolver.apply(claims);
    57	    }
    58	
