    63	    /**
    64	     * This method validates the detached json web signature with the supplied payload.
    65	     *
    66	     * @param detachedSignature
    67	     * @param payload
    68	     * @throws Exception
    69	     *             - if signature validation fails.
    70	     */
    71	    public boolean validateSign( String detachedSignature, String payload, JsonWebKeySet jsonWebKeySet )
    72	            throws JoseException
    73	    {
    74	
    75	        // Use a JsonWebSignature object to verify the signature
    76	        JsonWebSignature verifierJws = new JsonWebSignature();
    77	
    78	        // Set the algorithm constraints based on what is agreed upon or expected from
    79	        // the sender
    80	        verifierJws.setAlgorithmConstraints(new AlgorithmConstraints(AlgorithmConstraints.ConstraintType.WHITELIST,
    81	                AlgorithmIdentifiers.RSA_USING_SHA256));
    82	
    83	        // The JWS with detached content is the compact serialization
    84	        verifierJws.setCompactSerialization(detachedSignature);
    85	
    86	        // The unencoded detached content is the payload
    87	        verifierJws.setPayload(payload);
    88	
    89	        VerificationJwkSelector jwkSelector = new VerificationJwkSelector();
    90	
    91	        RsaJsonWebKey jwk = (RsaJsonWebKey) jwkSelector.select(verifierJws, jsonWebKeySet.getJsonWebKeys());
    92	
    93	        if(jwk == null){
    94	            return false;
    95	        }
    96	
    97	        // The public key is used to verify the signature
    98	        // This should be the public key of the sender.
    99	        verifierJws.setKey(jwk.getPublicKey());
   100	
   101	        // Check the signature
   102	        return verifierJws.verifySignature();
   103	    }
