            }
            else
            {
                log.error("Invalid Customer ID : " + customerId);
                throw new DataException(HttpStatus.BAD_REQUEST.getReasonPhrase(), "Invalid Customer ID",
                        HttpStatus.BAD_REQUEST);
            }
        }
        return null;
    }

