    private ConsentDetail buildConsentDetailByConsentTemplate( ConsentConfigurationRequest consentConfigurationRequest )
    {
        Long consentStart = System.currentTimeMillis();
        ConsentDetail consentDetail = new ConsentDetail();
        consentDetail.setConsentStart(DateTimeUtil.getISOTimeStamp(consentStart));
        consentDetail.setConsentTypes(consentConfigurationRequest.getConsentTypes());
        if (!NullEmptyUtils.isNullorEmpty(consentConfigurationRequest.getDataFilter())){
            consentDetail.setDataFilter(consentConfigurationRequest.getDataFilter());
        }
        consentDetail.setFiTypes(consentConfigurationRequest.getFiTypes());
        consentDetail.setConsentMode(consentConfigurationRequest.getConsentMode());
        if(!NullEmptyUtils.isNull(consentConfigurationRequest.getFetchType())){
            //if(consentConfigurationRequest.getFetchType().equals(ConsentRequestEnum.FetchType.PERIODIC)){
            consentDetail.setFrequency(consentConfigurationRequest.getFrequency());
            //}
        }
        consentDetail.setPurpose(consentConfigurationRequest.getPurpose());
        consentDetail.setFetchType(consentConfigurationRequest.getFetchType());
        consentDetail.setDataLife(new DataLife(
                ConsentRequestEnum.DataLifeUnit.valueOf(consentConfigurationRequest.getDataLife().getUnit().toString()),
                consentConfigurationRequest.getDataLife().getValue()));

        if( consentConfigurationRequest.getConsentExpiry().getUnit()
                .equals(ConsentConfigurationRequest.DataLifeUnit.MONTH) )
        {
            consentDetail.setConsentExpiry(DateTimeUtil.getAddedDate(consentStart, 0,
                    consentConfigurationRequest.getConsentExpiry().getValue()));
        }
        else
        {
            consentDetail.setConsentExpiry(DateTimeUtil.getAddedDate(consentStart,
                    consentConfigurationRequest.getConsentExpiry().getValue(), 0));
        }

        FIDataRange fiDataRange = new FIDataRange();
        fiDataRange.setTo(DateTimeUtil.getISOTimeStamp(System.currentTimeMillis()));

        //Calculating the from date
        if( consentConfigurationRequest.getFIDataRange().getUnit()
                .equals(ConsentConfigurationRequest.DataLifeUnit.MONTH) )
        {
            fiDataRange.setFrom(DateTimeUtil.getAddedDate(System.currentTimeMillis(), 0,
                    -1 * consentConfigurationRequest.getFIDataRange().getValue()));
        }
        else
        {
            fiDataRange.setFrom(DateTimeUtil.getAddedDate(System.currentTimeMillis(),
                    -1 * consentConfigurationRequest.getFIDataRange().getValue(), 0));
        }
        consentDetail.setFIDataRange(fiDataRange);

        return consentDetail;

    }

