 81	            throws IOException, ServletException
 82	    {
 83	        //setting log id
 84	        MDC.put(applicationConfigurationBean.getMdcLogId(), UUIDGenerator.generateUUID());
 85	
 86	        //custom caching servlet request
 87	        CachedBodyHttpServletRequest cachedBodyHttpServletRequest = new CachedBodyHttpServletRequest(
 88	                (HttpServletRequest) request);
 89	
 90	        //caching servlet response
 91	        ContentCachingResponseWrapper contentCachingResponseWrapper = new ContentCachingResponseWrapper(
 92	                (HttpServletResponse) response);
 93	
 94	        boolean checkTxnId = false;
 95	        String txnIdRequest = "";
 96	        try
 97	        {
 98	            String requestBody = HttpContentExtractorUtil
 99	                        .getDataByInputStream(cachedBodyHttpServletRequest.getInputStream());
100	            String signature = cachedBodyHttpServletRequest.getHeader(applicationConfigurationBean.getJwsSignature());
101	            String apiKey = cachedBodyHttpServletRequest.getHeader(applicationConfigurationBean.getAaApiKey());
102	
103	
104	            log.info("API End Point : {}", cachedBodyHttpServletRequest.getRequestURL().toString());
105	            log.info("Request Body : {}", requestBody);
106	            log.info("Signature : {}", signature);
107	            log.info("API Key : {}", apiKey);
108	            log.info("Request Method : {}", ((HttpServletRequest) request).getMethod());
109	
110	            if( cachedBodyHttpServletRequest.getServletPath().contains("/Notification")) {
111	                ObjectMapper objectMapper = new ObjectMapper();
112	                JsonNode jsonNode = objectMapper.readTree(requestBody);
113	
114	                JsonNode jsonNode1 = jsonNode.get("ver");
115	
116	                String aaId = headerTokenSignatureVerificationService.verifyAAApiKey(apiKey);
117	                headerTokenSignatureVerificationService.verifyXJwsSignature(signature, requestBody, aaId);
118	
