153	            contentCachingResponseWrapper.setContentType("application/json");
154	            contentCachingResponseWrapper.setStatus(HttpStatus.BAD_REQUEST.value());
155	        } catch ( JWSSignatureException e) {
156	            final InvalidRequestErrorResponse message = new InvalidRequestErrorResponse();
157	            message.setErrorMsg(e.getErrorMessage());
