import com.finbit.fiuadapter.webservice.utils.*;
import com.finbit.fiuadapter.webservice.constants.GeneralConstants;
import org.joda.time.DateTime;
import org.joda.time.DateTimeZone;
import java.nio.charset.StandardCharsets;
import java.text.SimpleDateFormat;
import java.util.Base64;
import java.util.TimeZone;
import java.util.UUID;

public class Scratch {
    static int fail = 0;
    static void ck(String what, boolean ok) {
        System.out.println((ok ? "PASS  " : "FAIL  ") + what);
        if (!ok) fail++;
    }

    public static void main(String[] args) throws Exception {
        // ---- UUID validation
        for (int i = 0; i < 5000; i++) {
            String u = UUIDGenerator.generateUUID();
            if (!UUIDGenerator.regaxUUIDvalidation(u)) { ck("generated uuid accepted: " + u, false); break; }
        }
        ck("random generated uuids accepted", true);
        ck("canonical v4 accepted", UUIDGenerator.regaxUUIDvalidation("f81d4fae-7dec-41d0-8765-00a0c91e6bf6"));
        ck("all-f v4 accepted", UUIDGenerator.regaxUUIDvalidation("ffffffff-ffff-4fff-bfff-ffffffffffff"));
        ck("all-0 v4 accepted", UUIDGenerator.regaxUUIDvalidation("00000000-0000-4000-8000-000000000000"));
        ck("short last group refused", !UUIDGenerator.regaxUUIDvalidation("f81d4fae-7dec-41d0-8765-00a0c91e6bf"));
        ck("long last group refused", !UUIDGenerator.regaxUUIDvalidation("f81d4fae-7dec-41d0-8765-00a0c91e6bf67"));
        ck("garbage refused", !UUIDGenerator.regaxUUIDvalidation("not-a-uuid"));
        ck("empty refused", !UUIDGenerator.regaxUUIDvalidation(""));
        ck("no dashes refused", !UUIDGenerator.regaxUUIDvalidation("f81d4fae7dec41d0876500a0c91e6bf6"));
        ck("non-hex refused", !UUIDGenerator.regaxUUIDvalidation("g81d4fae-7dec-41d0-8765-00a0c91e6bf6"));
        ck("trailing space refused", !UUIDGenerator.regaxUUIDvalidation("f81d4fae-7dec-41d0-8765-00a0c91e6bf6 "));

        // ---- ISO timestamp: 24h, round-trips through the inbound parser
        SimpleDateFormat sdf = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'");
        sdf.setTimeZone(TimeZone.getTimeZone("UTC"));
        long afternoon = new DateTime(2021, 3, 14, 13, 47, 25, 123, DateTimeZone.UTC).getMillis();
        String stamp = DateTimeUtil.getISOTimeStamp(afternoon);
        ck("afternoon stamp is 13:47 -> " + stamp, "2021-03-14T13:47:25.123Z".equals(stamp));
        long morning = new DateTime(2021, 3, 14, 1, 47, 25, 123, DateTimeZone.UTC).getMillis();
        ck("morning stamp unchanged", "2021-03-14T01:47:25.123Z".equals(DateTimeUtil.getISOTimeStamp(morning)));
        long midnight = new DateTime(2021, 3, 14, 0, 5, 0, 0, DateTimeZone.UTC).getMillis();
        ck("midnight is 00:05", "2021-03-14T00:05:00.000Z".equals(DateTimeUtil.getISOTimeStamp(midnight)));
        long noon = new DateTime(2021, 3, 14, 12, 0, 0, 0, DateTimeZone.UTC).getMillis();
        ck("noon is 12:00", "2021-03-14T12:00:00.000Z".equals(DateTimeUtil.getISOTimeStamp(noon)));
        long lateEve = new DateTime(2021, 3, 14, 23, 59, 59, 999, DateTimeZone.UTC).getMillis();
        ck("23:59 preserved", "2021-03-14T23:59:59.999Z".equals(DateTimeUtil.getISOTimeStamp(lateEve)));
        // round trip against the parse pattern used for inbound timestamps
        ck("round-trips through parser", sdf.parse(stamp).getTime() == afternoon);
        // getAddedDate keeps 24h too
        ck("getAddedDate 24h", DateTimeUtil.getAddedDate(afternoon, 1, 0).equals("2021-03-15T13:47:25.123Z"));

        // ---- NullEmptyUtils
        ck("null is empty", NullEmptyUtils.isNullorEmpty((String) null));
        ck("\"\" is empty", NullEmptyUtils.isNullorEmpty(""));
        ck("\" \" is empty", NullEmptyUtils.isNullorEmpty(" "));
        ck("\"   \\t\\n \" is empty", NullEmptyUtils.isNullorEmpty("   \t\n "));
        ck("\"null\" is empty", NullEmptyUtils.isNullorEmpty("null"));
        ck("\"abc\" not empty", !NullEmptyUtils.isNullorEmpty("abc"));
        ck("\" abc \" not empty", !NullEmptyUtils.isNullorEmpty(" abc "));
        ck("isRowNull blank row", NullEmptyUtils.isRowNull(new String[] { "", " ", null }));
        ck("isRowNull non blank row", !NullEmptyUtils.isRowNull(new String[] { "", " x " }));

        // ---- Base64Decoder over base64url payloads
        // build a payload whose base64url encoding really contains '-' and '_'
        String json = null;
        for (int i = 0; i < 100000; i++) {
            String candidate = "{\"consentId\":\"" + UUID.randomUUID() + "\",\"n\":" + i + "}";
            String enc = Base64.getUrlEncoder().withoutPadding()
                    .encodeToString(candidate.getBytes(StandardCharsets.UTF_8));
            if (enc.indexOf('-') >= 0 && enc.indexOf('_') >= 0) { json = candidate; break; }
        }
        String encoded = Base64.getUrlEncoder().withoutPadding().encodeToString(json.getBytes(StandardCharsets.UTF_8));
        ck("test vector uses base64url alphabet: " + encoded, encoded.indexOf('-') >= 0 && encoded.indexOf('_') >= 0);
        Object decoded = Base64Decoder.getDecodedObject(encoded, java.util.HashMap.class);
        ck("base64url payload decodes: " + decoded, decoded instanceof java.util.Map
                && ((java.util.Map<?, ?>) decoded).containsKey("consentId"));
        // plain (no -/_) payload still works
        String plain = "{\"a\":1}";
        String plainEnc = Base64.getUrlEncoder().withoutPadding().encodeToString(plain.getBytes(StandardCharsets.UTF_8));
        Object plainDec = Base64Decoder.getDecodedObject(plainEnc, java.util.HashMap.class);
        ck("plain payload still decodes: " + plainDec, ((java.util.Map<?, ?>) plainDec).containsKey("a"));

        // ---- GetDetachedBody (detached + full compact serialisation)
        ck("detached signature part", "sig".equals(GetDetachedBody.getDetached("hdr..sig")));
        ck("full compact signature part", "sig".equals(GetDetachedBody.getDetached("hdr.payload.sig")));

        System.out.println(fail == 0 ? "\nALL OK" : "\n" + fail + " FAILURES");
        if (fail != 0) System.exit(1);
    }
}

