import com.finbit.fiuadapter.webservice.service.consentinit.ConsentInitServiceImpl;

public class Scratch2 {
    static int fail = 0;
    static void ck(String what, boolean ok) {
        System.out.println((ok ? "PASS  " : "FAIL  ") + what);
        if (!ok) fail++;
    }
    static String v(ConsentInitServiceImpl s, String in) {
        try { return s.validateCustomerId(in); } catch (Exception e) { return "EX:" + e.getClass().getSimpleName(); }
    }
    public static void main(String[] a) {
        ConsentInitServiceImpl s = new ConsentInitServiceImpl();
        ck("vua -> aa handle", "@onemoney".equals(v(s, "9999999999@onemoney")));
        ck("hyphenated aa handle", "@dashboard-aa".equals(v(s, "abc123@dashboard-aa")));
        ck("padded vua trimmed", "@finvu".equals(v(s, "  9999999999@finvu  ")));
        ck("handle only", "@finvu".equals(v(s, "@finvu")));
        ck("missing handle rejected", v(s, "9999999999@").startsWith("EX:"));
        ck("no @ rejected", v(s, "9999999999").startsWith("EX:"));
        ck("null passthrough", v(s, null) == null);
        ck("empty passthrough", v(s, "") == null);
        ck("blank passthrough", v(s, "   ") == null);
        System.out.println(fail == 0 ? "\nALL OK" : "\n" + fail + " FAILURES");
        if (fail != 0) System.exit(1);
    }
}

